INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2729114, 380605, 40465, '<td valign="top">Cute!!</td>', 'Cute!!', '2006-08-15 11:08:37.000000', NULL, 1),
(2729124, 380742, 30049, '<td valign="top">Great subject.  The guy is perfect for this shot!  Couple of things holding back what could have been a tremendous shot; 1) the lighting is very harsh, 2) the image isn''t focused as well as it should be, 3) maximize your real estate - use 640px on the long side for better detail.<br/> <br/>The composition is very good, wonderful in fact...  Best of luck to you in the challenge.</td>', 'Great subject.  The guy is perfect for this shot!  Couple of things holding back what could have been a tremendous shot; 1) the lighting is very harsh, 2) the image isn''t focused as well as it should be, 3) maximize your real estate - use 640px on the long side for better detail. The composition is very good, wonderful in fact...  Best of luck to you in the challenge.', '2006-08-15 11:13:58.000000', NULL, 1),
