(2738972, 379729, 62815, '<td valign="top">I give you 10 for the message I hope to hear you somebody</td>', 'I give you 10 for the message I hope to hear you somebody', '2006-08-18 07:05:58.000000', NULL, 1),
(2739078, 380395, 30049, '<td valign="top">Took a minute to figure out what was going on with that second setting in the back.  Made me look longer, which is good thing I guess.  ;^)<br/> <br/>I like your selective desat choice on this, the title works, and the image is well presented and technically sound.  Well done!</td>', 'Took a minute to figure out what was going on with that second setting in the back.  Made me look longer, which is good thing I guess.  ;^) I like your selective desat choice on this, the title works, and the image is well presented and technically sound.  Well done!', '2006-08-18 08:51:32.000000', NULL, 1),
(2739083, 379861, 30049, '<td valign="top">You brave soul, bringing woody into this.  ;^)  Actually, I quite like it.  The DOF choice works well and I like the color selected for the background (rather than the standard black or white).  Well focused and sharp where needed.  Well done!</td>', 'You brave soul, bringing woody into this.  ;^)  Actually, I quite like it.  The DOF choice works well and I like the color selected for the background (rather than the standard black or white).  Well focused and sharp where needed.  Well done!', '2006-08-18 08:54:20.000000', NULL, 1),
(2739086, 378487, 30049, '<td valign="top">Clever take on the challenge theme.  Plenty of "peace" going around, but not as you''ve done.  Potential stock sales with this one I would think as well.  Normally I would say the lighting is a little harsh, but the shadows actually work to fill in the lines of your "drawing" here.  Should do well with this.  Good luck.</td>', 'Clever take on the challenge theme.  Plenty of "peace" going around, but not as you''ve done.  Potential stock sales with this one I would think as well.  Normally I would say the lighting is a little harsh, but the shadows actually work to fill in the lines of your "drawing" here.  Should do well with this.  Good luck.', '2006-08-18 08:56:37.000000', NULL, 1),
(2739087, 380291, 30049, '<td valign="top">Cool image.  Nice lighting and textures.  I know there''s a message in here somewhere, but I''m not reading it.  What is coming out of the grinder?</td>', 'Cool image.  Nice lighting and textures.  I know there''s a message in here somewhere, but I''m not reading it.  What is coming out of the grinder?', '2006-08-18 08:58:01.000000', NULL, 1),
(2739103, 379581, 24454, '<td valign="top">Nice tight crop.    I really like the composition of this one.   Nice touch also having that splash of red in all that green  :)   Good job!</td>', 'Nice tight crop.    I really like the composition of this one.   Nice touch also having that splash of red in all that green  :)   Good job!', '2006-08-18 09:11:38.000000', NULL, 1),
(2739314, 378855, 30049, '<td valign="top">Looks like goodman work.  ;^)  Nice image, better processing!  You''ve worked this over quite nicely, that is if you''re a grunge look fan.  I like how you''ve made the green peas pop with the other muted tones.  I''d say ''Good luck in the challenge'', but don''t think you really need it.  ;^)</td>', 'Looks like goodman work.  ;^)  Nice image, better processing!  You''ve worked this over quite nicely, that is if you''re a grunge look fan.  I like how you''ve made the green peas pop with the other muted tones.  I''d say ''Good luck in the challenge'', but don''t think you really need it.  ;^)', '2006-08-18 11:14:52.000000', NULL, 1),
(2739320, 379243, 30049, '<td valign="top">Even without the title you can get a sense of what the image is saying.  Very clever, and well executed.  Hope this does well for you.  Good luck!</td>', 'Even without the title you can get a sense of what the image is saying.  Very clever, and well executed.  Hope this does well for you.  Good luck!', '2006-08-18 11:16:07.000000', NULL, 1),
(2739332, 379535, 30049, '<td valign="top">This is a nice sharp, well lit, image for the most part.  Light could have been diffused a little, but I like the fact that you''ve used a good amount of light overall.  One distraction for me is the reflection of the bottle and glass.  I imagine you were trying to capture the wall reflection primarily, but I find the cutoff reflections a bit awkward.  Best of luck to you in the challenge.</td>', 'This is a nice sharp, well lit, image for the most part.  Light could have been diffused a little, but I like the fact that you''ve used a good amount of light overall.  One distraction for me is the reflection of the bottle and glass.  I imagine you were trying to capture the wall reflection primarily, but I find the cutoff reflections a bit awkward.  Best of luck to you in the challenge.', '2006-08-18 11:21:16.000000', NULL, 1),
(2739336, 377757, 30049, '<td valign="top">Simple, yet effective.  Good luck.</td>', 'Simple, yet effective.  Good luck.', '2006-08-18 11:22:11.000000', NULL, 1),
(2739337, 378763, 30049, '<td valign="top">Good detail and a perfect image for selective desat.  Nice placement of primary subjects in the framing of your image as well.  Good luck in the challenge.</td>', 'Good detail and a perfect image for selective desat.  Nice placement of primary subjects in the framing of your image as well.  Good luck in the challenge.', '2006-08-18 11:23:35.000000', NULL, 1),
(2739341, 380756, 30049, '<td valign="top">Simple, yet pleasing.  Nice use of diagonal lines.</td>', 'Simple, yet pleasing.  Nice use of diagonal lines.', '2006-08-18 11:24:51.000000', NULL, 1),
(2739344, 380137, 30049, '<td valign="top">Hope everyone is ok!  Cute.  ;^)</td>', 'Hope everyone is ok!  Cute.  ;^)', '2006-08-18 11:25:29.000000', NULL, 1),
(2739347, 379914, 30049, '<td valign="top">The things we do for challenge entries!  ;^)  Very clever.  I like the composition overall.  The foreground peas are not lit well enough and I think the white background could be whiter.  Overall, nicely done.  Good luck in the challenge.</td>', 'The things we do for challenge entries!  ;^)  Very clever.  I like the composition overall.  The foreground peas are not lit well enough and I think the white background could be whiter.  Overall, nicely done.  Good luck in the challenge.', '2006-08-18 11:27:10.000000', NULL, 1),
(2739394, 378773, 30049, '<td valign="top">The composition of this works well with nice lines and good balance it the objects used.  I think it''s a bit underexposed and the peas could have more impact if not frozen - JMO of course.  Good luck in the challenge.</td>', 'The composition of this works well with nice lines and good balance it the objects used.  I think it''s a bit underexposed and the peas could have more impact if not frozen - JMO of course.  Good luck in the challenge.', '2006-08-18 12:11:41.000000', NULL, 1),
(2739398, 380158, 30049, '<td valign="top">This is a really cute idea.  Put this on a black (or dark) background with a spotlight type effect in lighting and you''d score a couple of points higher in the challenge I think.  As is, it''s a little grainy and slightly overexposed.  The ''escapee'' also blends in too much (hence the spotlight idea).  Anyway, best of luck to you in the challenge.</td>', 'This is a really cute idea.  Put this on a black (or dark) background with a spotlight type effect in lighting and you''d score a couple of points higher in the challenge I think.  As is, it''s a little grainy and slightly overexposed.  The ''escapee'' also blends in too much (hence the spotlight idea).  Anyway, best of luck to you in the challenge.', '2006-08-18 12:14:49.000000', NULL, 1),
(2739399, 379535, 55247, '<td valign="top">beautiful</td>', 'beautiful', '2006-08-18 12:15:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2739404, 378185, 30049, '<td valign="top">Need to work on lighting (multiple light sources that are diffused/bounced will help).  The light glare on the glass is harsh (glasses also look dirty).<br/>Subject matter is a matter of personal preference, but I find the layout here a bit static and kind of "ho-hum".  JMO of course.  Best of luck to you, and keep at it...</td>', 'Need to work on lighting (multiple light sources that are diffused/bounced will help).  The light glare on the glass is harsh (glasses also look dirty).Subject matter is a matter of personal preference, but I find the layout here a bit static and kind of "ho-hum".  JMO of course.  Best of luck to you, and keep at it...', '2006-08-18 12:18:47.000000', NULL, 1),
