(2739589, 379186, 57882, '<td valign="top">Well framed.  Great tones.</td>', 'Well framed.  Great tones.', '2006-08-18 13:57:43.000000', NULL, 1),
(2739592, 379679, 20530, '<td valign="top">This image is so surreal. I love it. The sunrays from behind the mountain create such a nice effect. The foreground is very unusual and interesting. Great humor with the "wandering" peas. That second one looks like the salt is getting to him...starting to wrinkle. Nice lighting and great composition. Hope it does well!</td>', 'This image is so surreal. I love it. The sunrays from behind the mountain create such a nice effect. The foreground is very unusual and interesting. Great humor with the "wandering" peas. That second one looks like the salt is getting to him...starting to wrinkle. Nice lighting and great composition. Hope it does well!', '2006-08-18 14:00:13.000000', NULL, 1),
