(2749346, 379729, 59215, '<td valign="top">Hey there:) I think it came out pretty well! I didn''t vote since I knew it was yours but thought I''d comment now that voting is over and such. <br/> <br/>I agree with one of your other commenters, that maybe a diff perspective might have helped the peace symbol stand out better. Also, my first impression was that the lighting is a little harsh- dark pea shadows in contrast to the highlights on the left being a bit blown, but overall a cool idea!<br/> <br/></td>', 'Hey there:) I think it came out pretty well! I didn''t vote since I knew it was yours but thought I''d comment now that voting is over and such.  I agree with one of your other commenters, that maybe a diff perspective might have helped the peace symbol stand out better. Also, my first impression was that the lighting is a little harsh- dark pea shadows in contrast to the highlights on the left being a bit blown, but overall a cool idea! ', '2006-08-22 17:09:55.000000', NULL, 0),
(2749421, 378763, 2240, '<td valign="top">Nice picture Les. Congrats on top ten.</td>', 'Nice picture Les. Congrats on top ten.', '2006-08-22 17:39:41.000000', NULL, 0),
(2749425, 380753, 2240, '<td valign="top">Well done Shannon !</td>', 'Well done Shannon !', '2006-08-22 17:42:30.000000', NULL, 0),
(2749433, 378763, 19708, '<td valign="top">Considering how bad selective desats do on this site, this was really done well and worthy of top 5.<br/>Congrats on the <img alt="'' . substr(''//www.dpchallenge.com/images/ribbig5.gif'', strrpos(''//www.dpchallenge.com/images/ribbig5.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/ribbig5.gif"/> Place Honorable Mention!<br/><br/><i>Message edited by author 2006-08-22 16:45:05.</i></td>', 'Considering how bad selective desats do on this site, this was really done well and worthy of top 5.Congrats on the  Place Honorable Mention!', '2006-08-22 17:44:54.000000', '2006-08-22 17:45:05.000000', 0),
(2749441, 379662, 2240, '<td valign="top">Congrats on your first ribbon.</td>', 'Congrats on your first ribbon.', '2006-08-22 17:47:06.000000', NULL, 0),
(2749456, 379186, 2240, '<td valign="top">Wonderful idea. Congrats on the Blue.</td>', 'Wonderful idea. Congrats on the Blue.', '2006-08-22 17:51:05.000000', NULL, 0),
(2749489, 379186, 56725, '<td valign="top">very nice editing on the photo!!</td>', 'very nice editing on the photo!!', '2006-08-22 18:02:26.000000', NULL, 0),
(2749491, 379186, 48680, '<td valign="top">Congrats on your blue ribbon!!<br/>cute shot :)<br/>&amp; thanks too for sharing the original, interesting</td>', 'Congrats on your blue ribbon!!cute shot :)& thanks too for sharing the original, interesting', '2006-08-22 18:03:45.000000', NULL, 0),
(2749508, 380753, 48680, '<td valign="top">original idea :)<br/>congrats on your ribbon!</td>', 'original idea :)congrats on your ribbon!', '2006-08-22 18:08:33.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2749513, 380705, 60698, '<td valign="top">Nice finish. You are movin'' up!</td>', 'Nice finish. You are movin'' up!', '2006-08-22 18:11:04.000000', NULL, 0),
(2749520, 377870, 33352, '<td valign="top">You really like these top 50 finishes, well done with a great story.</td>', 'You really like these top 50 finishes, well done with a great story.', '2006-08-22 18:13:48.000000', NULL, 0),
(2749529, 378175, 48389, '<td valign="top">This is a nice fun shot and I like the placement of the face in the frame but there are definitely a few things you could improve on. The image is quite pixelated, my instinct is to put this down to a resizing problem, maybe you need to look at how your resizing your images? There are some blue and white marks on the B/G and at the edges of the peas...was the B/G originally a different colour? Dealing with these two issues would definitely get you a better score in my opinion :o)</td>', 'This is a nice fun shot and I like the placement of the face in the frame but there are definitely a few things you could improve on. The image is quite pixelated, my instinct is to put this down to a resizing problem, maybe you need to look at how your resizing your images? There are some blue and white marks on the B/G and at the edges of the peas...was the B/G originally a different colour? Dealing with these two issues would definitely get you a better score in my opinion :o)', '2006-08-22 18:19:05.000000', NULL, 0),
(2749543, 377322, 49326, '<td valign="top">I love your idea :) Pretty nice. I like his "sleeping" expression. It''s like he has too much peas around his head and has fallen asleep because of that. I don''t know why he would do that but It looks like he did that.</td>', 'I love your idea :) Pretty nice. I like his "sleeping" expression. It''s like he has too much peas around his head and has fallen asleep because of that. I don''t know why he would do that but It looks like he did that.', '2006-08-22 18:24:24.000000', NULL, 0),
(2749571, 380705, 38930, '<td valign="top">This is awesome!!  You have an amazing concept, we just need to work on the actual photograph a little bit - great job though!</td>', 'This is awesome!!  You have an amazing concept, we just need to work on the actual photograph a little bit - great job though!', '2006-08-22 18:31:30.000000', NULL, 0),
(2749589, 379768, 48389, '<td valign="top">I really like the composition, the hand is entering the frame nicely and you have a nice depth of field. You probably lost a few points here as these are kidney beans rather than Peas but other than that I quite like this image.</td>', 'I really like the composition, the hand is entering the frame nicely and you have a nice depth of field. You probably lost a few points here as these are kidney beans rather than Peas but other than that I quite like this image.', '2006-08-22 18:36:20.000000', NULL, 0),
(2749615, 380705, 60614, '<td valign="top">I just wanted to thank everyone who to date has left me comments concerning this photo.  I know it takes time to vote and comment so I appreciate it very much.  This is such a fun site and I love looking at everyone''s photos. Everyone is so talented in their own way.  I am learning alot from everyone.  Thank you again.<br/> <br/>Happy shooting.</td>', 'I just wanted to thank everyone who to date has left me comments concerning this photo.  I know it takes time to vote and comment so I appreciate it very much.  This is such a fun site and I love looking at everyone''s photos. Everyone is so talented in their own way.  I am learning alot from everyone.  Thank you again. Happy shooting.', '2006-08-22 18:43:53.000000', NULL, 0),
(2749798, 379186, 60047, '<td valign="top">Wow. The difference between your unedited version and your submission is inspiring for someone like me who is trying to learn Photoshop. Your editing really made this photo stand out. Congrats.</td>', 'Wow. The difference between your unedited version and your submission is inspiring for someone like me who is trying to learn Photoshop. Your editing really made this photo stand out. Congrats.', '2006-08-22 19:50:01.000000', NULL, 0),
(2749804, 379186, 48115, '<td valign="top">hehe she looks just like you my man :) good job.. haltu áfram að standa þig strákur!</td>', 'hehe she looks just like you my man :) good job.. haltu áfram að standa þig strákur!', '2006-08-22 19:54:32.000000', NULL, 0),
(2749820, 380753, 12253, '<td valign="top">Congratulations Shannon!  You always know just what to do!</td>', 'Congratulations Shannon!  You always know just what to do!', '2006-08-22 20:08:26.000000', NULL, 0),
(2749888, 379873, 22301, '<td valign="top">I agree killing pees=exactly what everyone else should hva done too, lol, congrats on the 6+</td>', 'I agree killing pees=exactly what everyone else should hva done too, lol, congrats on the 6+', '2006-08-22 20:39:55.000000', NULL, 0),
(2750018, 379186, 20941, '<td valign="top">Congratulations on Your Blue with this adorable shot!</td>', 'Congratulations on Your Blue with this adorable shot!', '2006-08-22 21:34:26.000000', NULL, 0),
(2750025, 380753, 20941, '<td valign="top">Great lighting and PP! Congrats on your Ribbon Shannon! Fantastic concept and execution as always! Your house must be full of great props and models!</td>', 'Great lighting and PP! Congrats on your Ribbon Shannon! Fantastic concept and execution as always! Your house must be full of great props and models!', '2006-08-22 21:38:53.000000', NULL, 0),
(2750035, 379662, 20941, '<td valign="top">Congratulations on your first ribbon! With technical ability like this, I''m sure there will be more to come! Outstanding work</td>', 'Congratulations on your first ribbon! With technical ability like this, I''m sure there will be more to come! Outstanding work', '2006-08-22 21:41:50.000000', NULL, 0),
(2750089, 378166, 31307, '<td valign="top">Wow, 2 in a row for you....You are getting a lot of mileage out of this one.  (Fyi it was not me that gave you the 10).  Word to the wise, though, the natives grow restless with this one.  You might be carved open, stuffed with blue peas, and then slow roasted over a blue flame (fueled by your many brown ribbons) till tender...<br/> <br/>You might try going for the "Photographer of most questionable work" persona on DPC and use roughly the same image every time.  But then you would probably get to the point where everyone took it upon theirselves to give you a 10 and ruin your shot at the brown and, as a whole, end up handing you the blue.  Hmm...coincidence in your choice of color?</td>', 'Wow, 2 in a row for you....You are getting a lot of mileage out of this one.  (Fyi it was not me that gave you the 10).  Word to the wise, though, the natives grow restless with this one.  You might be carved open, stuffed with blue peas, and then slow roasted over a blue flame (fueled by your many brown ribbons) till tender... You might try going for the "Photographer of most questionable work" persona on DPC and use roughly the same image every time.  But then you would probably get to the point where everyone took it upon theirselves to give you a 10 and ruin your shot at the brown and, as a whole, end up handing you the blue.  Hmm...coincidence in your choice of color?', '2006-08-22 22:08:12.000000', NULL, 0),
(2750115, 379186, 17203, '<td valign="top">Great, just what I needed... another phenomenal prodigy to kick my butt! ;-)<br/> <br/>Fabulous shot (one of two 10 votes I gave out). The eyes make it  for me. Congrats on the well deserved blue!</td>', 'Great, just what I needed... another phenomenal prodigy to kick my butt! ;-) Fabulous shot (one of two 10 votes I gave out). The eyes make it  for me. Congrats on the well deserved blue!', '2006-08-22 22:14:57.000000', NULL, 0),
(2750139, 380753, 42567, '<td valign="top">Another great shot Shannon!  Congratulations!</td>', 'Another great shot Shannon!  Congratulations!', '2006-08-22 22:23:55.000000', NULL, 0),
(2750205, 378682, 63395, '<td valign="top">thanks for your comments! Um, the ''rest of it'' is chopsticks, a plate and a wood table runner. thats it.</td>', 'thanks for your comments! Um, the ''rest of it'' is chopsticks, a plate and a wood table runner. thats it.', '2006-08-22 22:47:25.000000', NULL, 0),
(2750325, 379186, 35804, '<td valign="top">A most adorable little pea pixie, excellent work young Magnús!</td>', 'A most adorable little pea pixie, excellent work young Magnús!', '2006-08-22 23:40:35.000000', NULL, 0),
(2750401, 380728, 43298, '<td valign="top">Hahhahaha, we''re side by side! This is cool, a very different look on a pea!</td>', 'Hahhahaha, we''re side by side! This is cool, a very different look on a pea!', '2006-08-23 00:08:11.000000', NULL, 0),
(2750428, 380688, 63360, '<td valign="top">Maybe there were a few TOO MANY peas on her cute face!</td>', 'Maybe there were a few TOO MANY peas on her cute face!', '2006-08-23 00:13:39.000000', NULL, 0),
(2750477, 380753, 38248, '<td valign="top">Your creativity and attention to detail always inspire me.  Absolutely impressive.  Very clean and professional.  This is a powerful photo. The photo and the title fit well together. This speaks volumes about your imagination, talent, and vision. I think it''s wonderful that your wife and family understand and help you create and project your art and your vision.  Sorry, don''t mean to ramble.<br/> <br/>Congratulations,<br/>Stephen</td>', 'Your creativity and attention to detail always inspire me.  Absolutely impressive.  Very clean and professional.  This is a powerful photo. The photo and the title fit well together. This speaks volumes about your imagination, talent, and vision. I think it''s wonderful that your wife and family understand and help you create and project your art and your vision.  Sorry, don''t mean to ramble. Congratulations,Stephen', '2006-08-23 00:26:33.000000', NULL, 0),
(2750516, 380623, 39702, '<td valign="top">Totally agree with SandyP. This does not deserve a 4.8!  You got robbed.  Nice work.</td>', 'Totally agree with SandyP. This does not deserve a 4.8!  You got robbed.  Nice work.', '2006-08-23 00:47:46.000000', NULL, 0),
(2750520, 380753, 43298, '<td valign="top">Simply perfect :)</td>', 'Simply perfect :)', '2006-08-23 00:49:14.000000', NULL, 0),
(2750641, 378763, 48560, '<td valign="top">great picture. wow that pea really stood out in a nice way.<br/>I like the desat, and hey, congrats on the 5th!</td>', 'great picture. wow that pea really stood out in a nice way.I like the desat, and hey, congrats on the 5th!', '2006-08-23 01:26:09.000000', NULL, 0),
(2750663, 379873, 48560, '<td valign="top">dramatic, lol<br/>you never fail to impress me with your "sick" ideas, Ken.<br/>NICE SHOT (and I mean it, it''s not a copy &amp; paste, hehe)</td>', 'dramatic, lolyou never fail to impress me with your "sick" ideas, Ken.NICE SHOT (and I mean it, it''s not a copy & paste, hehe)', '2006-08-23 01:31:21.000000', NULL, 0),
(2750673, 380537, 48560, '<td valign="top">the tones were great. suprised this didn''t do better.<br/>you might want to consider putting this up on stock photo sites :)</td>', 'the tones were great. suprised this didn''t do better.you might want to consider putting this up on stock photo sites :)', '2006-08-23 01:32:34.000000', NULL, 0),
(2750959, 380745, 16241, '<td valign="top">sweet pic, good saturation, congrats.</td>', 'sweet pic, good saturation, congrats.', '2006-08-23 02:20:54.000000', NULL, 0),
(2751054, 380537, 41337, '<td valign="top">I love this shot. Amazing what you can do when you''re not shooting peppers. :P</td>', 'I love this shot. Amazing what you can do when you''re not shooting peppers. :P', '2006-08-23 02:57:18.000000', NULL, 0),
(2751149, 379186, 37779, '<td valign="top">You''re too amazing.</td>', 'You''re too amazing.', '2006-08-23 03:35:01.000000', NULL, 0),
(2751215, 377870, 18450, '<td valign="top">His expression is priceless!! Original, creative and way too funny!! Great work Judy.....selective desat is perfect for this shot.</td>', 'His expression is priceless!! Original, creative and way too funny!! Great work Judy.....selective desat is perfect for this shot.', '2006-08-23 04:17:07.000000', NULL, 0),
(2752135, 377870, 37961, '<td valign="top">I like the strange color desat and overall mood. Would like to have seen more of his mouth though. Title is good!</td>', 'I like the strange color desat and overall mood. Would like to have seen more of his mouth though. Title is good!', '2006-08-23 10:39:05.000000', NULL, 0),
(2752184, 377322, 30982, '<td valign="top">Wow - that there is a LOT of peas.  Very creative approach to the challenge and have to admit I wouldn''t have gone to all that work for a shot of peas.  :-)  Seems to have been well-received.  Nice work with the 50mm, by the way - good choice there.  And I have to say I didn''t know there was an aperture of 4.3 - is there?  Technicals are good - nice use of ambient light (you do that so well).  Maybe a bit too green on the peas, but not by much,</td>', 'Wow - that there is a LOT of peas.  Very creative approach to the challenge and have to admit I wouldn''t have gone to all that work for a shot of peas.  :-)  Seems to have been well-received.  Nice work with the 50mm, by the way - good choice there.  And I have to say I didn''t know there was an aperture of 4.3 - is there?  Technicals are good - nice use of ambient light (you do that so well).  Maybe a bit too green on the peas, but not by much,', '2006-08-23 10:56:44.000000', NULL, 0),
(2753088, 379186, 52296, '<td valign="top">Wonderful shot Magnus, congrats on the ribbon!</td>', 'Wonderful shot Magnus, congrats on the ribbon!', '2006-08-23 15:23:21.000000', NULL, 0),
(2753163, 379873, 35357, '<td valign="top">Sweet, LOL!  Needs some blood. ;-)</td>', 'Sweet, LOL!  Needs some blood. ;-)', '2006-08-23 15:43:21.000000', NULL, 0),
(2753185, 378401, 47274, '<td valign="top">i really like this</td>', 'i really like this', '2006-08-23 15:48:30.000000', NULL, 0),
(2753772, 380753, 32997, '<td valign="top">so very effective because of the simplicity...well done and congrats on the ribbon...</td>', 'so very effective because of the simplicity...well done and congrats on the ribbon...', '2006-08-23 17:55:40.000000', NULL, 0),
(2754096, 380395, 42100, '<td valign="top">Surprised nobody commented that your peas are making a mercedes symbol and not the "peas" symbol.  You are seriously getting your moneys worth from that Sigma, wish I could say the same.  What the difference a little thing like talent makes, and you''ve got loads.  ''Grats on another great photo!</td>', 'Surprised nobody commented that your peas are making a mercedes symbol and not the "peas" symbol.  You are seriously getting your moneys worth from that Sigma, wish I could say the same.  What the difference a little thing like talent makes, and you''ve got loads.  ''Grats on another great photo!', '2006-08-23 19:21:52.000000', NULL, 0),
(2754140, 379662, 54917, '<td valign="top">Simplicity and adeptness - well deserved! Hope there''s more to come.</td>', 'Simplicity and adeptness - well deserved! Hope there''s more to come.', '2006-08-23 19:39:40.000000', NULL, 0),
